window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7b2ac7308d494f09"]={"versions": [{"id": "FIG-7b2ac7308d494f09", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm mit eingebetteten Zustandsinvarianten/Zustandssymbolen aus der AUTOSAR Classic Platform (SWS CAN State Manager). Es spezifiziert das dynamische Verhalten der Bus-Off-Recovery-Zustandsmaschine (BusOffRecovery StM) bei der Rückkehr aus dem Zustand <code>CANSM_BOR_CHECK_L1</code> in den Zustand <code>CANSM_BOR_NO_BUS_OFF</code> im Kontext der zyklischen Ausführung von <code>CanSM_MainFunction()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>SchM::SchM</code> (Schedule Manager / BSW-Scheduler als Aufrufer)\n</li><li><code>Com::Com</code> (AUTOSAR COM-Modul, passive Lebenslinie)\n</li><li><code>Dem::Dem</code> (Diagnostic Event Manager, passive Lebenslinie)\n</li><li><code>CanSM::CanSM</code> (CAN State Manager als ausführendes Modul)\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>Aufruf: <code>CanSM_MainFunction()</code> von <code>SchM</code> an <code>CanSM</code>\n</li><li>Lokaler Selbstaufruf/Zuweisung: <code>Bus-off counter := 0()</code> an der Lebenslinie von <code>CanSM</code>\n</li><li>Referenzierte Sequenzen (<code>ref</code>):\n<ul class=\"fig-list\"><li><code>Bus-off recovery StM: Report passed to DEM</code>\n</li><li><code>Bus-off recovery StM: Switch on RX deadline monitoring</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Zustandsentitäten (<code>from BusOffRecovery</code>):</p>\n<ul class=\"fig-list\"><li>Ausgangszustand: <code>CANSM_BOR_CHECK_L1</code>\n</li><li>Zielzustand: <code>CANSM_BOR_NO_BUS_OFF</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Schedule Manager (<code>SchM</code>) ruft synchron <code>CanSM_MainFunction()</code> auf <code>CanSM</code> auf.\n</li><li>Ein übergeordneter <code>loop</code>-Kombinationsrahmen iteriert über jedes konfigurierte CAN-Netzwerk-Handle (<code>For every configured CAN network handle</code>).\n</li><li>Für Netzwerke im Zustand <code>CANSM_BOR_CHECK_L1</code> erfolgt eine Verzweigung über einen <code>alt</code>-Rahmen (<code>Check timer in CANSM_BOR_CHECK_L1</code>):\n<ul class=\"fig-list\"><li>Zweig <code>[timer &gt;= CANSM_BOR_TIME_TX_ENSURED]</code>:\n<ul class=\"fig-list\"><li>Der Bus-Off-Zähler wird zurückgesetzt (<code>Bus-off counter := 0()</code>).\n</li><li>Ausführung des referenzierten Ablaufs <code>Bus-off recovery StM: Report passed to DEM</code> (Erfolgsmeldung an das Dem).\n</li><li>Ausführung des referenzierten Ablaufs <code>Bus-off recovery StM: Switch on RX deadline monitoring</code> (Aktivierung der RX-Deadline-Überwachung in Com).\n</li><li>Die Zustandsmaschine wechselt in den Zustand <code>CANSM_BOR_NO_BUS_OFF</code>.\n</li></ul>\n</li><li>Zweig <code>[timer &lt; CANSM_BOR_TIME_TX_ENSURED]</code>:\n<ul class=\"fig-list\"><li>Keine weiteren Aktionen; der Zustand <code>CANSM_BOR_CHECK_L1</code> bleibt bestehen.\n</li></ul>\n</li></ul>\n</li><li>Nach Durchlauf der Schleife kehrt der Aufruf von <code>CanSM_MainFunction()</code> zum <code>SchM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Ablauf definiert die zeitgesteuerte Bestätigung einer erfolgreichen Bus-Off-Wiederherstellung (Level 1 Recovery): Erst wenn die konfigurierte Mindestzeit für garantierten Sende-/Empfangsbetrieb (<code>CANSM_BOR_TIME_TX_ENSURED</code>) ohne erneuten Bus-Off abgelaufen ist, gilt der Bus als stabil.\n</li><li>Das Zurücksetzen des internen Bus-Off-Fehlerzählers auf 0 verhindert die Eskalation in höhere Wiederherstellungsstufen (Level 2).\n</li><li>Die Benachrichtigung des Dem (<code>Report passed</code>) schließt den Fehlerpfad diagnostisch ab.\n</li><li>Die Reaktivierung des Empfangs-Deadline-Monitorings (<code>Com</code>) stellt den regulären Überwachungsbetrieb für Kommunikationsausfälle wieder her.\n</li><li>Implementierer müssen sicherstellen, dass Timer-Inkrementierung und Zustandsübergänge konsistent je CAN-Netzwerk-Instanz im zyklischen MainFunction-Raster verarbeitet werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2e6da1ac04f7b7b4", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm mit eingebetteten Zustandsinvarianten/Zustandssymbolen aus der AUTOSAR Classic Platform (SWS CAN State Manager). Es spezifiziert das dynamische Verhalten der Bus-Off-Recovery-Zustandsmaschine (BusOffRecovery StM) bei der Rückkehr aus dem Zustand <code>CANSM_BOR_CHECK_L1</code> in den Zustand <code>CANSM_BOR_NO_BUS_OFF</code> im Kontext der zyklischen Ausführung von <code>CanSM_MainFunction()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>SchM::SchM</code> (Schedule Manager / BSW-Scheduler als Aufrufer)\n</li><li><code>Com::Com</code> (AUTOSAR COM-Modul, passive Lebenslinie)\n</li><li><code>Dem::Dem</code> (Diagnostic Event Manager, passive Lebenslinie)\n</li><li><code>CanSM::CanSM</code> (CAN State Manager als ausführendes Modul)\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>Aufruf: <code>CanSM_MainFunction()</code> von <code>SchM</code> an <code>CanSM</code>\n</li><li>Lokaler Selbstaufruf/Zuweisung: <code>Bus-off counter := 0()</code> an der Lebenslinie von <code>CanSM</code>\n</li><li>Referenzierte Sequenzen (<code>ref</code>):\n<ul class=\"fig-list\"><li><code>Bus-off recovery StM: Report passed to DEM</code>\n</li><li><code>Bus-off recovery StM: Switch on RX deadline monitoring</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Zustandsentitäten (<code>from BusOffRecovery</code>):</p>\n<ul class=\"fig-list\"><li>Ausgangszustand: <code>CANSM_BOR_CHECK_L1</code>\n</li><li>Zielzustand: <code>CANSM_BOR_NO_BUS_OFF</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Schedule Manager (<code>SchM</code>) ruft synchron <code>CanSM_MainFunction()</code> auf <code>CanSM</code> auf.\n</li><li>Ein übergeordneter <code>loop</code>-Kombinationsrahmen iteriert über jedes konfigurierte CAN-Netzwerk-Handle (<code>For every configured CAN network handle</code>).\n</li><li>Für Netzwerke im Zustand <code>CANSM_BOR_CHECK_L1</code> erfolgt eine Verzweigung über einen <code>alt</code>-Rahmen (<code>Check timer in CANSM_BOR_CHECK_L1</code>):\n<ul class=\"fig-list\"><li>Zweig <code>[timer &gt;= CANSM_BOR_TIME_TX_ENSURED]</code>:\n<ul class=\"fig-list\"><li>Der Bus-Off-Zähler wird zurückgesetzt (<code>Bus-off counter := 0()</code>).\n</li><li>Ausführung des referenzierten Ablaufs <code>Bus-off recovery StM: Report passed to DEM</code> (Erfolgsmeldung an das Dem).\n</li><li>Ausführung des referenzierten Ablaufs <code>Bus-off recovery StM: Switch on RX deadline monitoring</code> (Aktivierung der RX-Deadline-Überwachung in Com).\n</li><li>Die Zustandsmaschine wechselt in den Zustand <code>CANSM_BOR_NO_BUS_OFF</code>.\n</li></ul>\n</li><li>Zweig <code>[timer &lt; CANSM_BOR_TIME_TX_ENSURED]</code>:\n<ul class=\"fig-list\"><li>Keine weiteren Aktionen; der Zustand <code>CANSM_BOR_CHECK_L1</code> bleibt bestehen.\n</li></ul>\n</li></ul>\n</li><li>Nach Durchlauf der Schleife kehrt der Aufruf von <code>CanSM_MainFunction()</code> zum <code>SchM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Ablauf definiert die zeitgesteuerte Bestätigung einer erfolgreichen Bus-Off-Wiederherstellung (Level 1 Recovery): Erst wenn die konfigurierte Mindestzeit für garantierten Sende-/Empfangsbetrieb (<code>CANSM_BOR_TIME_TX_ENSURED</code>) ohne erneuten Bus-Off abgelaufen ist, gilt der Bus als stabil.\n</li><li>Das Zurücksetzen des internen Bus-Off-Fehlerzählers auf 0 verhindert die Eskalation in höhere Wiederherstellungsstufen (Level 2).\n</li><li>Die Benachrichtigung des Dem (<code>Report passed</code>) schließt den Fehlerpfad diagnostisch ab.\n</li><li>Die Reaktivierung des Empfangs-Deadline-Monitorings (<code>Com</code>) stellt den regulären Überwachungsbetrieb für Kommunikationsausfälle wieder her.\n</li><li>Implementierer müssen sicherstellen, dass Timer-Inkrementierung und Zustandsübergänge konsistent je CAN-Netzwerk-Instanz im zyklischen MainFunction-Raster verarbeitet werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7b2ac7308d494f09", "to": "FIG-2e6da1ac04f7b7b4", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
